#include "verificationwidget.h"
#include <QtSql>
#include <QtWidgets>
#include <algorithm>

namespace { void fill(QComboBox*c,QSqlDatabase db,const QString&sql,const QString&all){QSignalBlocker b(c);int old=c->currentData().toInt();c->clear();c->addItem(all,-1);QSqlQuery q(db);if(q.exec(sql))while(q.next())c->addItem(q.value(1).toString(),q.value(0));int i=c->findData(old);c->setCurrentIndex(i<0?0:i);} }

VerificationWidget::VerificationWidget(QWidget*parent):QWidget(parent){
  auto*layout=new QVBoxLayout(this);auto*filters=new QHBoxLayout;
  m_pt=new QComboBox;m_document=new QComboBox;m_status=new QComboBox;m_type=new QComboBox;m_method=new QComboBox;m_coverage=new QComboBox;m_coverage->addItem("Toutes",-1);m_coverage->addItem("Couvertes",1);m_coverage->addItem("Manquantes",0);m_obsolete=new QCheckBox("Inclure les obsolètes");
  for(auto p:QList<QPair<QString,QWidget*>>{{"Branche PT",m_pt},{"Document",m_document},{"Statut",m_status},{"Type",m_type},{"Méthode",m_method},{"Couverture",m_coverage}}){filters->addWidget(new QLabel(p.first));filters->addWidget(p.second);}filters->addWidget(m_obsolete);filters->addStretch();auto*exportButton=new QPushButton("Exporter XLSX…");filters->addWidget(exportButton);layout->addLayout(filters);
  m_rate=new QLabel;layout->addWidget(m_rate);m_matrix=new QTableWidget;m_matrix->setObjectName("verificationMatrix");m_matrix->setEditTriggers(QAbstractItemView::NoEditTriggers);m_matrix->setSelectionBehavior(QAbstractItemView::SelectRows);m_matrix->setSortingEnabled(true);m_matrix->setAlternatingRowColors(true);m_matrix->horizontalHeader()->setStretchLastSection(true);layout->addWidget(m_matrix,1);
  for(auto*c:{m_pt,m_document,m_status,m_type,m_method,m_coverage})
    connect(c,QOverload<int>::of(&QComboBox::currentIndexChanged),this,&VerificationWidget::refreshMatrix);
  connect(m_obsolete,&QCheckBox::toggled,this,&VerificationWidget::refreshMatrix);
  connect(m_matrix,&QTableWidget::cellDoubleClicked,this,[this](int row,int){if(row>=0)editRequirement(m_matrix->item(row,0)->data(Qt::UserRole).toInt());});
  connect(exportButton,&QPushButton::clicked,this,[this]{QString path=QFileDialog::getSaveFileName(this,"Exporter la matrice","matrice-verification.xlsx","Classeur Excel (*.xlsx)");if(path.isEmpty())return;if(!path.endsWith(".xlsx",Qt::CaseInsensitive))path+=".xlsx";auto r=m_service.exportXlsx(path,filter());if(r.success)QMessageBox::information(this,"Export XLSX",r.message);else QMessageBox::warning(this,"Export XLSX",r.message);});
}
void VerificationWidget::setConnectionName(const QString&name){m_connection=name;m_service.setConnectionName(name);refresh();}
VerificationFilter VerificationWidget::filter()const{VerificationFilter f;f.ptRootId=m_pt->currentData().toInt();f.documentId=m_document->currentData().toInt();f.statusId=m_status->currentData().toInt();f.typeId=m_type->currentData().toInt();f.methodId=m_method->currentData().toInt();f.coverage=m_coverage->currentData().toInt();f.includeObsolete=m_obsolete->isChecked();return f;}
void VerificationWidget::refresh(){QSqlDatabase db=QSqlDatabase::database(m_connection,false);if(m_connection.isEmpty()||!db.isValid()||!db.isOpen()){m_matrix->setRowCount(0);return;}fill(m_pt,db,"SELECT ID,NAME FROM PT WHERE ARCHIVED=0 ORDER BY POSITION,NAME","Toutes");fill(m_document,db,"SELECT ID,COALESCE(NULLIF(REFERENCE,''),TITLE) FROM DOCUMENT ORDER BY TITLE","Tous");fill(m_status,db,"SELECT ID,STATUS FROM REQ_STATUS ORDER BY ID","Tous");fill(m_type,db,"SELECT ID,TYPE FROM REQ_TYPE ORDER BY TYPE","Tous");fill(m_method,db,"SELECT ID,METHOD FROM REQ_METHOD ORDER BY METHOD","Toutes");refreshMatrix();}
void VerificationWidget::refreshMatrix(){if(m_connection.isEmpty())return;QString error;m_rows=m_service.matrix(filter(),&error);m_matrix->setSortingEnabled(false);m_matrix->setColumnCount(10);m_matrix->setHorizontalHeaderLabels({"Code","Titre","Statut","Type","Product Trees","Documents","Méthodes","Niveaux PT","Lignes","Couverture"});m_matrix->setRowCount(m_rows.size());for(int r=0;r<m_rows.size();++r){const auto&x=m_rows[r];QStringList values{x.code,x.title,x.status,x.type,x.productTrees,x.documents,x.methods,x.levels,QString::number(x.verificationCount),x.covered?"Couverte":"Manquante"};for(int c=0;c<values.size();++c)m_matrix->setItem(r,c,new QTableWidgetItem(values[c]));m_matrix->item(r,0)->setData(Qt::UserRole,x.requirementId);if(!x.covered)for(int c=0;c<m_matrix->columnCount();++c)m_matrix->item(r,c)->setBackground(QColor("#fce8e6"));}m_matrix->setSortingEnabled(true);m_rate->setText(QString("Taux de couverture : %1 % — %2 exigences. Double-cliquer pour planifier ou ouvrir l’exigence.").arg(m_service.coverageRate(m_rows),0,'f',2).arg(m_rows.size()));if(!error.isEmpty())m_rate->setText(error);}
void VerificationWidget::editRequirement(int req){
  auto it=std::find_if(m_rows.begin(),m_rows.end(),[req](const auto&r){return r.requirementId==req;});if(it==m_rows.end())return;QDialog d(this);d.setWindowTitle("Plan de vérification — "+it->code);d.resize(1150,450);auto*l=new QVBoxLayout(&d);auto*t=new QTableWidget;t->setColumnCount(8);t->setHorizontalHeaderLabels({"Méthode","Niveau PT","Procédure / cas","Redmine","Moyen","Verdict","Commentaire",""});t->horizontalHeader()->setStretchLastSection(true);l->addWidget(t);QSqlDatabase db=QSqlDatabase::database(m_connection);QList<QPair<int,QString>> methods,levels;QSqlQuery q(db);if(q.exec("SELECT ID,METHOD FROM REQ_METHOD ORDER BY METHOD"))while(q.next())methods<<qMakePair(q.value(0).toInt(),q.value(1).toString());if(q.exec("SELECT ID,NAME FROM PT WHERE ARCHIVED=0 ORDER BY POSITION,NAME"))while(q.next())levels<<qMakePair(q.value(0).toInt(),q.value(1).toString());
  auto add=[&](const RequirementVerification&v){int row=t->rowCount();t->insertRow(row);auto*m=new QComboBox;m->setProperty("verificationId",v.id);for(auto x:methods)m->addItem(x.second,x.first);m->setCurrentIndex(qMax(0,m->findData(v.methodId)));t->setCellWidget(row,0,m);auto*p=new QComboBox;p->addItem("—",-1);for(auto x:levels)p->addItem(x.second,x.first);if(v.levelPtId>=0&&p->findData(v.levelPtId)<0)p->addItem(v.level+" [archivé]",v.levelPtId);p->setCurrentIndex(qMax(0,p->findData(v.levelPtId)));t->setCellWidget(row,1,p);for(int c=2;c<=6;++c)t->setItem(row,c,new QTableWidgetItem());t->item(row,2)->setText(v.procedure);t->item(row,3)->setText(v.redmine);t->item(row,4)->setText(v.means);auto*verdict=new QComboBox;verdict->addItems({"","C","PC","NC"});verdict->setCurrentText(v.verdict);t->setCellWidget(row,5,verdict);t->item(row,6)->setText(v.comment);auto*actions=new QWidget;auto*al=new QHBoxLayout(actions);al->setContentsMargins(0,0,0,0);auto*up=new QPushButton("↑"),*down=new QPushButton("↓"),*remove=new QPushButton("×");al->addWidget(up);al->addWidget(down);al->addWidget(remove);t->setCellWidget(row,7,actions);auto locate=[t,actions]{for(int r=0;r<t->rowCount();++r)if(t->cellWidget(r,7)==actions)return r;return -1;};connect(remove,&QPushButton::clicked,&d,[t,locate]{int r=locate();if(r>=0)t->removeRow(r);});connect(up,&QPushButton::clicked,&d,[t,locate]{int r=locate();if(r>0)for(int c=0;c<t->columnCount();++c){auto*w=t->cellWidget(r,c);auto*i=t->takeItem(r,c);auto*w2=t->cellWidget(r-1,c);auto*i2=t->takeItem(r-1,c);if(w)t->removeCellWidget(r,c);if(w2)t->removeCellWidget(r-1,c);if(w)t->setCellWidget(r-1,c,w);if(w2)t->setCellWidget(r,c,w2);if(i)t->setItem(r-1,c,i);if(i2)t->setItem(r,c,i2);}});connect(down,&QPushButton::clicked,&d,[t,locate]{int r=locate();if(r>=0&&r<t->rowCount()-1)for(int c=0;c<t->columnCount();++c){auto*w=t->cellWidget(r,c);auto*i=t->takeItem(r,c);auto*w2=t->cellWidget(r+1,c);auto*i2=t->takeItem(r+1,c);if(w)t->removeCellWidget(r,c);if(w2)t->removeCellWidget(r+1,c);if(w)t->setCellWidget(r+1,c,w);if(w2)t->setCellWidget(r,c,w2);if(i)t->setItem(r+1,c,i);if(i2)t->setItem(r,c,i2);}});};for(const auto&v:it->verifications)add(v);connect(t,&QTableWidget::cellDoubleClicked,&d,[t](int r,int c){if(c==3){QUrl url=QUrl::fromUserInput(t->item(r,c)->text());if(url.isValid()&&!url.scheme().isEmpty())QDesktopServices::openUrl(url);}});auto*addButton=new QPushButton("Ajouter une méthode");l->addWidget(addButton);connect(addButton,&QPushButton::clicked,&d,[&]{add({});});QDialogButtonBox buttons(QDialogButtonBox::Save|QDialogButtonBox::Cancel);l->addWidget(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&d,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&d,&QDialog::reject);if(d.exec()!=QDialog::Accepted){emit openRequirementRequested(req);return;}QList<RequirementVerification> rows;for(int r=0;r<t->rowCount();++r){RequirementVerification v;auto*method=qobject_cast<QComboBox*>(t->cellWidget(r,0));v.id=method->property("verificationId").toInt();v.methodId=method->currentData().toInt();v.levelPtId=qobject_cast<QComboBox*>(t->cellWidget(r,1))->currentData().toInt();v.level=qobject_cast<QComboBox*>(t->cellWidget(r,1))->currentText();v.procedure=t->item(r,2)->text();v.redmine=t->item(r,3)->text();v.means=t->item(r,4)->text();v.verdict=qobject_cast<QComboBox*>(t->cellWidget(r,5))->currentText();v.comment=t->item(r,6)->text();rows<<v;}auto result=m_service.save(req,rows);if(!result.success)QMessageBox::warning(this,"Vérification",result.message);else{refreshMatrix();emit dataChanged();}}
